### updateMessage

This adds a new `updateMessage` mutation for marking messages as `spam`:

```graphql
mutation {
  updateMessage(input: { id: "25", spam: true }) {
    conversationOrError {
      __typename
      ... on UpdateMessageSuccess {
        conversation {
          initialMessage
        }
      }
      ... on UpdateMessageFailure {
        mutationError {
          message
        }
      }
    }
  }
}
```

### updateCMSLastAccessTimestampMutation

```graphql
mutation {
  updateCMSLastAccessTimestamp(input: { id: "25" }) {
    partnerOrError {
      __typename
      ... on UpdateCMSLastAccessTimestampSuccess {
        partner {
          internalID
        }
      }
      ... on UpdateCMSLastAccessTimestampFailure {
        mutationError {
          message
        }
      }
    }
  }
}
```

### deleteConversation

This deletes a conversation by ID:

```graphql
mutation {
  deleteConversation(input: { id: "25" }) {
    conversationOrError {
      __typename
      ... on DeleteConversationSuccess {
        conversation {
          deletedAt
        }
      }
      ... on DeleteConversationFailure {
        mutationError {
          message
        }
      }
    }
  }
}
```

### updateConversation

```graphql
mutation updateConversation($input: UpdateConversationMutationInput!) {
  updateConversation(input: $input) {
    conversation {
      internalID
    }
  }
}
```

